Optimal string alignment (restricted Damerau–Levenshtein) distance via dynamic programming:

```python
def edit_distance(a: str, b: str) -> int:
    n, m = len(a), len(b)
    if n == 0:
        return m
    if m == 0:
        return n

    d = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        d[i][0] = i
    for j in range(m + 1):
        d[0][j] = j

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            best = min(
                d[i - 1][j] + 1,        # deletion
                d[i][j - 1] + 1,        # insertion
                d[i - 1][j - 1] + cost  # substitution / match
            )
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                best = min(best, d[i - 2][j - 2] + 1)  # transposition
            d[i][j] = best

    return d[n][m]


assert edit_distance('kitten', 'sitting') == 3
assert edit_distance('ab', 'ba') == 1
```

Each cell considers deletion, insertion, substitution, and (when the last two characters are swapped) a single transposition from `d[i-2][j-2]`, which enforces the "no substring edited twice" restriction of OSA.
